// /frontend-react/src/components/SideMenu.js

import React from 'react';

const MenuItem = ({ name, emoji, onClick, isEasyMode }) => (
    <div
        onClick={onClick}
        style={{
            display: 'flex',
            alignItems: 'center',
            padding: '20px 15px',
            borderBottom: '1px solid #eee',
            cursor: 'pointer',
            backgroundColor: 'white',
            transition: 'background-color 0.1s',
        }}
        onMouseOver={e => e.currentTarget.style.backgroundColor = '#f0f0f0'}
        onMouseOut={e => e.currentTarget.style.backgroundColor = 'white'}
    >
        <span role="img" aria-label={name} style={{
            fontSize: isEasyMode ? '40px' : '28px',
            marginRight: '15px',
            flexShrink: 0,
        }}>{emoji}</span>
        
        <span style={{
            fontSize: isEasyMode ? '26px' : '18px',
            fontWeight: 'bold',
            color: '#333',
        }}>{name}</span>
    </div>
);

function SideMenu({ isEasyMode, isOpen, onClose, goToPage }) {

    if (!isOpen) {
        return null; // Don't render if not open
    }
    
    const handleLogout = () => {
        console.log("Action: Logging out...");
        alert("Logged out successfully! Redirecting to login screen.");
        onClose();
        goToPage('dashboard'); 
    };

    const handleProfile = () => {
        console.log("Action: Viewing Profile...");
        alert("Redirecting to Profile settings.");
        onClose();
    };

    const handleLanguage = () => {
        console.log("Action: Changing Language...");
        alert("Redirecting to Language settings (e.g., Audio/Text Language).");
        onClose();
    };

    return (
        <div style={{
            position: 'absolute',
            top: 0,
            right: 0,
            height: '100%',
            width: '80%', 
            backgroundColor: '#fff',
            boxShadow: '-8px 0 20px rgba(0,0,0,0.5)',
            zIndex: 100,
            transition: 'transform 0.3s ease-out',
            transform: isOpen ? 'translateX(0)' : 'translateX(100%)',
            overflowY: 'auto',
        }}>
            {/* Header/Close Button (Cleaner Look) */}
            <div style={{ 
                padding: '18px 25px', 
                borderBottom: '2px solid #ddd', 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center', 
                backgroundColor: '#1A73E8', 
                color: 'white',
            }}>
                <h3 style={{ margin: 0, fontSize: isEasyMode ? '34px' : '22px' }}>Menu</h3>
                <button 
                    onClick={onClose} 
                    style={{ 
                        background: 'none', 
                        border: 'none', 
                        color: 'white', 
                        fontSize: isEasyMode ? '34px' : '28px', 
                        cursor: 'pointer' 
                    }}
                >
                    &times;
                </button>
            </div>

            {/* Menu Items */}
            <MenuItem 
                name="👤 Profile" 
                emoji="👤" 
                onClick={handleProfile} 
                isEasyMode={isEasyMode}
            />
            <MenuItem 
                name="🗣️ Language" 
                emoji="🗣️" 
                onClick={handleLanguage} 
                isEasyMode={isEasyMode}
            />
            <MenuItem 
                name="🚪 Logout" 
                emoji="🚪" 
                onClick={handleLogout} 
                isEasyMode={isEasyMode}
            />
        </div>
    );
}

export default SideMenu;
